INSERT INTO _legacy_rows VALUES
  (63, 'artikel', 'Teknologi Baru, Ventilator Bisa Bantu Pernapasan Pasien COVID 19', '<p>&nbsp;</p><p>1. Tim Yogya (YPTI, Swayasa, UGM, STECHOQ) mengembangkan Ventilator lokal dengan dua macam<br>spesifikasi:<br>a. Ventilator Tipe Low Cost<br>b. Ventilator Tipe Advance</p><p>Ventilator yang kami kembangkan ini menggunakan komponen-komponen yang memenuhi<br>Standard Medical Grade, bukan part-part yang ada di market.</p><p>2.Dalam menentukan spesifikasi detail, kami juga disupport oleh Tim Kedokteran R.S. Dr Sardjito –<br>UGM.</p><p>④Pada saat ini, kami sedang dalam progress untuk pembuatan Prototype dan kami targetkan untuk<br>bisa mulai produksi di bulan Mei untuk Tipe Low Cost dan bulan Juni untuk Tipe Advance.</p><p>3.Dalam rangka menuju tahapan production, kami terus berkoordinasi dengan Kemenprind-<br>Direktorat Jenderal ILMATE (IPAMP dan IMATAP) untuk mendapatkan support agar target untuk<br>memulai produksi bisa dicapai.</p>', 'teknologi-baru-ventilator-bisa-bantu-pernapasan-pasien-covid-19', 'http://api-stg.demoserver.id/media/uploads/c997b6b7b8ae4401b1eb4a3926f0cd90.jpeg', 'PUBLISH', '2022-10-21', '2022-10-21 17:00:00', NULL, NULL),
  (64, 'artikel', 'Ground Breaking Indonesia Manufacturing Center', '<p>Senin, 5 Desember 2022<br>&nbsp;</p><p><img src="http://kemenperin.go.id/download/28633"><br>Menteri Perindustrian Agus Gumiwang Kartasasmita menyampaikan sambutannya saat ground breaking Indonesia Manufacturing Center (IMC) di Purwakarta, Jawa Barat, 5 Desember 2022. Menperin menyampaikan, pembangunan IMC bertujuan untuk mengkolaborasikan seluruh pemangku kepentingan yang mempunyai peranan penting di bidang pengembangan teknologi industri.</p><p>&nbsp;</p><p>&nbsp;</p><p><img src="http://kemenperin.go.id/download/28634"></p><p>Menteri Perindustrian Agus Gumiwang Kartasasmita yang didampingi oleh Sekjen Kementerian Perindustrian (Kemenperin) Dody Widodo (kiri), Kepala BPKP Muhammad Yusuf Ateh (dua dari kiri), Staff Khusus Menteri ESDM Agus Tjahajana Wirakusumah (kanan), Bupati Purwakarta, Anne Ratna Mustika (dua dari kanan), serta Menteri Koperasi dan UKM Teten Masduki (tiga dari kanan) memencet tombol tanda dimulainya pembangunan IMC di Purwakarta, Jawa Barat, 5 Desember 2022.</p>', 'ground-breaking-indonesia-manufacturing-center', 'http://api-stg.demoserver.id/media/uploads/1a9f1f19789148f6ade66a2c9bf4c210.jpeg', 'PUBLISH', '2022-10-19', '2022-10-19 17:00:00', NULL, NULL),
  (65, 'artikel', 'Apa Itu Era Society 5.0 dan Apa Perbedaannya dengan Era Industri 4.0?', '<p>Kemajuan teknologi yang dibuat oleh manusia seiring waktu semakin maju dan berkembang. Salah satunya ialah Society 5.0 yang digagas oleh negara Jepang. Konsep ini memungkinkan kita menggunakan ilmu pengetahuan yang berbasis modern seperti IoT, AI dan Robot untuk kebutuhan manusia dengan tujuan agar manusia dapat hidup dengan nyaman dan lebih efektif. Society 5.0 sendiri baru saja diresmikan 2 tahun yang lalu, pada 21 Januari 2019 dan dibuat sebagai resolusi atas resolusi <a href="http://barki.uma.ac.id/">industri 4.0</a>.</p><p>Konsep Industri 4.0 dan Society 5.0 pada dasarnya tidak memiliki perbedaan yang jauh, akan tetapi konsep Society lebih focus pada konteks terhadap manusia. Jika revolusi industri menggunakan AI, dan kecerdasan buatan sebagai komponen utamanya sedangkan Society 5.0 menggunakan teknologi modern hanya saja mengandalkan manusia sebagai komponen utamanya.</p><p>Konsep Society 5.0 merupakan penyempurnaan dari konsep-konsep yang ada sebelumnya. Dimana seperti kita ketahui, Society 1.0 adalah pada saat manusia masih berada di era berburu dan mengenal tulisan, Society 2.0 adalah era pertanian dimana manusia sudah mengenal bercocok tanam, Society 3.0 : sudah memasuki era industry yaitu Ketika manusia sudah mulai menggunakan mesin untuk membantu aktivitas sehari-hari, Society 4.0: manusia sudah mengenal computer hingga internet dan Society 5.0 era dimana semua teknologi adalah bagian dari manusia itu sendiri, internet bukan hanya digunakan untuk sekedar berbagi informasi melainkan untuk menjalani kehidupan.</p><p>Dalam Society 5.0 dimana komponen utamanya adalah manusia yang mampu menciptakan nilai baru melalui perkembangan teknologi dapat meminimalisir adanya kesenjangan pada manusia dan masalah ekonomi dikemudian hari. Memang rasanya sulit dilakukan di negara berkembang seperti Indonesia, namun bukan berarti tidak bisa dilakukan karena saat ini Negara Jepang sudah membuktikannya sebagai Negara dengan teknologi yang paling maju.</p>', 'apa-itu-era-society-50-dan-apa-perbedaannya-dengan-era-industri-40', '/upload/5cbe42a6-a1eb-4535-ade1-2c30595002f8.png', 'PUBLISH', '2022-10-20', '2022-10-20 17:00:00', NULL, NULL),
  (73, 'infographic', 'Indonesia Official Partner Country Hannover Messe 2020', '<p>Indonesia Official Partner Country Hannover Messe 2020</p>', 'indonesia-official-partner-country-hannover-messe-2020', 'https://api.demoserver.id/media/uploads/ff78cb943d394f23b048be55b431d682.jpeg', 'PUBLISH', NULL, NULL, NULL, NULL),
  (74, 'infographic', 'Di Hannover Messe 2020, RI Unjuk Taji Industri 4.0 dan Gaet Investasi', '<p>Di Hannover Messe 2020, RI Unjuk Taji Industri 4.0 dan Gaet Investasi</p>', 'di-hannover-messe-2020-ri-unjuk-taji-industri-40-dan-gaet-investasi', 'https://api.demoserver.id/media/uploads/0ab75c17c69c43ad94c588b471589cca.png', 'PUBLISH', NULL, NULL, NULL, NULL),
  (75, 'event', 'IMC Dorong Peningkatan Kandungan Komponen Lokal Alat Cuci Darah Lewat Kolaborasi Industri', '<p><strong>Jakarta, 16 Desember 2024</strong> – Indonesia Manufacturing Center (IMC) terus memperkuat perannya dalam mendorong kemandirian industri alat kesehatan nasional. Melalui workshop bertajuk <i>"Peran Indonesia Manufacturing Center (IMC) dalam Kolaborasi untuk Mendukung Optimalisasi Pelokalan Komponen Alat Kesehatan Hemodialisis (Alat Cuci Darah),"</i> IMC mengajak seluruh pemangku kepentingan untuk bergandengan tangan menghadapi tantangan kebutuhan mesin cuci darah yang terus meningkat di Indonesia.</p><p>Acara yang digelar di Hotel Bidakara, Jakarta ini menghadirkan berbagai pihak penting dari pemerintah, industri, lembaga riset, asosiasi, hingga rumah sakit. Diskusi berlangsung aktif dan menunjukkan urgensi kolaborasi untuk mengurangi ketergantungan terhadap impor alat kesehatan, khususnya mesin hemodialisis dan komponennya.</p><h3>Meningkatnya Kebutuhan, Minim Produksi Lokal</h3><p>Dalam pembukaan, Ketua Tim Kerja Penguatan IMC, Mangasi Parsaoran Siahaan, menegaskan pentingnya penguatan industri alat kesehatan dalam negeri. Data dari Indonesia Renal Registry mencatat lonjakan rata-rata pasien gagal ginjal sebesar 32,5% per tahun dalam lima tahun terakhir. Mesin hemodialisis menjadi kebutuhan utama, namun sebagian besar masih diimpor.</p><p>“Kita harus memastikan layanan kesehatan strategis seperti hemodialisis bisa terpenuhi dengan produk buatan dalam negeri. Di sinilah IMC hadir sebagai fasilitator dan katalisator kolaborasi antar pemangku kepentingan,” ujarnya.</p><h3>Potensi Dalam Negeri Besar, Perlu Disinergikan</h3><p>Kementerian Kesehatan melalui Zulfikar Biruni menyampaikan bahwa Indonesia memiliki 832 produsen alat kesehatan dengan lebih dari 15.000 jenis produk. Namun, komponen mesin cuci darah—seperti dialyzer dan mesin dialisis—masih bergantung pada impor. Padahal, produksi lokal dialyzer oleh PT Forsta Kalmedic Global telah membuktikan potensi besar industri nasional.</p><p>Direktur PT Forsta, Yvone Astri Della Sijabat, mengungkap bahwa perusahaannya telah berhasil memproduksi dialyzer dengan tingkat kandungan dalam negeri (TKDN) di atas 40%. Namun ia menyoroti tantangan besar yang dihadapi pelaku industri lokal, mulai dari kebutuhan investasi, transfer teknologi, hingga kepastian penyerapan pasar.</p><h3>Peran IMC Sebagai Jembatan Kolaborasi</h3><p>Ketua Tim Persiapan Operasional IMC, Cuk Subagio, memaparkan bahwa IMC dirancang sebagai pusat kolaborasi teknologi dan manufaktur. IMC akan menjadi tempat berkumpulnya industri, akademisi, lembaga riset, hingga pemerintah untuk mengembangkan produk strategis, termasuk alat kesehatan.</p><p>“IMC menawarkan layanan dari hulu ke hilir, mulai dari pengembangan produk, pelatihan SDM manufaktur, digitalisasi proses industri, hingga promosi dan jejaring bisnis. Kita ingin menciptakan ekosistem industri alat kesehatan yang kuat dan mandiri,” jelasnya.</p><p>Sebagai tindak lanjut, IMC akan:</p><ul><li>Menyusun <strong>peta jalan pelokalan komponen hemodialisis</strong>,</li><li>Memfasilitasi <strong>kolaborasi riset dan rekayasa produk</strong> bersama BRIN, perguruan tinggi, dan industri,</li><li>Mengembangkan <strong>database kemampuan industri nasional</strong> agar sinergi lebih efektif,</li><li>Mendorong <strong>regulasi protektif dan keberpihakan pasar</strong> bagi produk dalam negeri.</li></ul><p>Workshop ini menjadi titik tolak penting untuk membangun kesadaran kolektif bahwa kemandirian alat kesehatan bukan sekadar pilihan, tetapi kebutuhan strategis nasional. IMC, sebagai inisiatif Kementerian Perindustrian, siap menjadi penggerak perubahan menuju industri manufaktur Indonesia yang lebih kuat, inovatif, dan berdaya saing global.</p>', NULL, '/upload/2500ae41-91b0-480b-b9ab-e5ebfe9f6113.png', 'PUBLISH', '2024-12-14', '2024-12-15 17:00:00', '2024-12-14 17:00:00', NULL),
  (76, 'infographic', 'Industri Ban Nasional makin kompetitif', '<p>Industri Ban Nasional makin kompetitif</p>', 'industri-ban-nasional-makin-kompetitif', 'https://imc-api-dev.kemenperin.go.id/dashboard/public/upload/dce920e9-0bc9-43d7-9edf-cad246360b85.png', 'PUBLISH', NULL, NULL, NULL, NULL),
  (77, 'infographic', 'Industri Ban Nasional makin kompetitif', '<p>Industri Ban Nasional makin kompetitif</p>', 'industri-ban-nasional-makin-kompetitif', 'https://api.demoserver.id/media/uploads/4a49fb4d1e1a49ab829ccb4a46eeb92f.jpeg', 'PUBLISH', NULL, NULL, NULL, NULL),
  (191, 'news', 'Hebat, Temuan Balai Kemenperin Ini Bisa Dimanfaatkan Industri Alat Pertahanan', '<p>Hebat, Temuan Balai Kemenperin Ini Bisa Dimanfaatkan Industri Alat Pertahanan<br>Pada ajang Indo Defence 2022, Balai Besar Standardisasi dan Pelayanan Jasa Industri (BBSPJI) Agro membawa teknologi proses pengujian makanan untuk keperluan militer. “Selama ini kami memberikan jasa layanan teknis kepada masyarakat dan industri agro seperti industri makanan dan minuman, serta industri pupuk,” ujar Kepala BBSPJI Agro, Siti Rohmah Siregar.</p><p>&nbsp;</p><p>Kemudian, BBSPJI Logam dan Mesin menampilkan rantai tapak atau <i>track link</i> lapis baja untuk tank. Komponen ini bagian dari rantai tank yang menapak pada jalan dan secara keseluruhan berfungsi untuk menggerakan kendaraan tempur tersebut.</p><p>&nbsp;</p><p>“Keunggulan desain <i>track link</i> ini adalah terdapat bantalan karet yang dapat mengurangi kebisingan suara tank dan lebih nyaman untuk dibawa di jalan beraspal. Modifikasi bentuk tersebut merupakan salah satu faktor yang mendukung penelitian ini dalam memperoleh paten. Kelebihan lainnya, <i>track link</i> yang kami buat bisa berjalan di lumpur karena dilengkapi bagian serupa sayap-sayap kecil atau dayung,” ungkap Kepala BBSPJI Logam dan Mesin, Gunawan.</p><p>&nbsp;</p><p>Berikutnya, partisipasi BBSPJI Keramik dan Mineral Nonlogam dalam penguatan sektor pertahanan, yakni membuat produk rompi tahan peluru, helm tahan peluru serta produk pelapis kendaraan militer sebagai substitusi baja. Untuk penemuan helm tahan peluru, dilakukan melalui kerja sama riset dengan Balitbang Kementerian Pertahanan dan PT Pindad. Hasil ini telah mendapatkan paten dengan Nomor ID P 0028082 pada April 2011 lalu dan siap untuk dikomersialkan.</p><p>&nbsp;</p><p>“Kami senantiasa mendukung kemajuan dan kemampuan industri alat pertahanan dalam negeri. Kami juga berharap hasil yang kami kembangkan dapat mengatasi ketergantungan Indonesia pada teknologi dari luar negeri,” ujar Kepala BBSPJI Keramik dan Mineral Nonlogam, Azhar Fitri.</p><p>&nbsp;</p><p>Selanjutnya, BBSPJI Tekstil memperkenalkan aplikasi kitosan untuk antibakteri pada seragam militer. Kitosan adalah produk samping hasil laut asal Indonesia, di mana memiliki sifat alami antibakteri dengan kemampuan reduksi pertumbuhan bakteri pada tekstil hingga lebih dari 90%.</p><p>&nbsp;</p><p>“Dengan adanya <i>finishing agent chitogiene</i> ini, pakaian seragam tidak mudah bau keringat meskipun tidak dicuci beberapa hari. Hal ini tentu dapat meningkatkan unsur kenyamanan dan sanitasi pribadi para prajurit TNI atau Polri,” tutur Kepala BBSPJI Tekstil, Cahyadi.</p><p>&nbsp;</p><p>Selain itu, BBSPJI Selulosa menampilkan penggunaan nitro selulosa sebagai bahan dasar propelan untuk pendorong roket. Selama ini kebutuhan nitro selulosa masih sangat tergantung impor. Oleh karenanya dalam rangka mewujudkan kemandirian industri pertahanan, BBSPJI Selulosa bekerjasama dengan PT. Dahana untuk mengembangkan <i>dissolving pulp</i> sebagai bahan baku nitro selulosa.</p><p>&nbsp;</p><p>Kepala BBSPJI Selulosa, Sri Bimo Pratomo menyampaikan bahwa peluang pemanfaatan bahan baku serat selulosa Indonesia masih sangat besar karena ketersediaannya cukup berlimpah, di mana salah satunya adalah pemanfaatan Eucalyptus dan Bambu Gombong menjadi nitro selulosa. “Kami sedang berupaya mengimplementasikan pemanfaatan selulosa ini menjadi produk yang bernilai tambah tinggi untuk kemandirian bangsa,” terangnya.</p><p>&nbsp;</p><p>Kemenperin juga memfasilitasi Asosiasi Sistem &amp; Teknologi Tanpa Awak (ASTTA) tampil di ajang Indo Defence 2022, untuk memperkenalkan berbagai produk drone dalam negeri yang bisa mendukung sektor pertahanan dan keamanan nasional. Apalagi, saat ini teknologi drone pertahanan merupakan topik yang semakin ramai menjadi perbincangan sejak konflik Rusia dan Ukraina.</p><p>&nbsp;</p><p>Di samping itu, semakin banyak negara yang mulai tertarik dengan efektivitas teknologi drone yang telah terbukti di medan pertempuran. Di Indonesia sendiri telah terdapat beberapa perusahaan manufaktur drone yang mampu mengembangkan teknologi tersebut dan tergabung di dalam ASTTA.</p><p>&nbsp;</p><p>Ketua Umum ASTTA Dian Rusdiana Hakim mengapresiasi upaya Kemenperin dalam mempromosikan kemampuan industri drone lokal melalui berbagai kegiatan pameran internasional seperti Indo Defence. “Saya berharap kemampuan industri drone lokal dapat lebih banyak dimanfaatkan oleh pemerintah untuk menjaga pertahanan Indonesia sendiri, sebelum dilirik oleh negara lain,” ujarnya.</p><p>Demikian Siaran Pers ini untuk disebarluaskan.</p>', 'hebat-temuan-balai-kemenperin-ini-bisa-dimanfaatkan-industri-alat-pertahanan', '', 'PUBLISH', '2022-11-07', '2022-11-07 12:45:12', NULL, NULL),
  (192, 'news', 'Kinerja Mulus Industri Kulit Nasional, Tanzania Belajar dari Indonesia', '<p>Industri kulit merupakan salah satu subsektor industri pengolahan nonmigas yang memiliki kinerja positif. Ini tercermin pada capaian produk domestik bruto (PDB) atas dasar harga konstan (ADHK) di industri kulit, barang dari kulit, dan alas kaki yang menembus Rp7,57 triliun pada kuartal II tahun 2022.</p><p>&nbsp;</p><p>Capaian tersebut mengalami kenaikan hingga 13,12% secara tahunan (<i>y-o-y</i>) apabila dibandingkan pada periode yang sama tahun sebelumnya sebesar Rp6,7 triliun. Kenaikan ini didorong tingginya permintaan ekspor, investasi, serta pengalihan order ke Indonesia.</p><p>&nbsp;</p><p>“Ketersediaan sumber daya manusia (SDM) yang kompeten menjadi salah satu faktor mulusnya kinerja industri kulit nasional. Untuk terus meningkatkan kualitas tenaga kerja di industri kulit, Kementerian Perindustrian memiliki unit pendidikan vokasi melalui Politeknik Akademi Teknologi Kulit Yogyakarta (Politeknik ATK Yogyakarta),” kata Kepala Badan Pengembangan Sumber Daya Manusia Industri (BPSDMI) Kemenperin, Arus Gunawan di Jakarta, Rabu (26/10).</p><p>&nbsp;</p><p>Arus mengemukakan, Politeknik ATK Yogyakarta telah berdiri sejak tahun 1954. Kampus yang genap berusia 68 tahun ini sudah banyak mencetak pekerja dan wirausaha industri di bidang pemrosesan kulit serta memproduksi berbagai produk kulit seperti jaket, sepatu, tas, dan sarung tangan.</p><p>&nbsp;</p><p>“Politeknik ini memang memiliki kekhususan di bidang pemrosesan kulit. Artinya, unit pendidikan vokasi kami spesifik dan teknis, dengan menerapkan model pendidikan <i>dual system</i> yang berbasis kompetensi,” ungkapnya.</p><p>&nbsp;</p><p>Beberapa waktu lalu, BPSDMI Kemenperin menggelar pelatihan tentang penyamakan kulit di Politeknik ATK Yogyakarta. Pelatihan ini merupakan wujud nyata dari kerja sama Indonesia dan Tanzania. “Indonesia menjadi <i>Pivotal Partner</i> atau sebagai pihak yang membagikan pengetahuan dan keahlian di bidang industri kulit melalui Politeknik ATK Yogyakarta,” tuturKepala Pusat Pengembangan Pendidikan Vokasi Industri BPSDMI Kemenperin, Restu Yuni Widayati.</p><p>&nbsp;</p><p>Sedangkan, Tanzania selaku <i>Beneficiary Partner</i> atau menjadi pihak yang mempelajari pengetahuan dan keahlian dari <i>Pivotal Partner,</i> dengan target pelatihan sesuai kebutuhan dan prioritas industri kulit di negara tersebut. “Kerja sama ini juga didukung oleh Jerman selaku <i>Facilitating Partner</i> yang membantu menghubungkan kedua negara dan mendukung penyelenggaraan kegiatan,” papar Restu.</p><p>&nbsp;</p><p>Kerja sama <i>triangular cooperation </i>atau kerja sama tiga negara antara Indonesia, Tanzania, dan Jerman ini telah direncanakan, diimplementasikan, dan dievaluasi oleh program South-South Triangular Cooperation (SSTC) Technical and Vocational Educational Training (TVET). Pembiayaan program dilakukan secara <i>co-sharing</i> dari pihak-pihak yang terlibat.</p><p>&nbsp;</p><p>“Adapun tujuan dari kerja sama tiga negara ini adalah transfer pengetahuan dan keahlian terkait industri kulit agar sumber daya manusia industri kulit Tanzania lebih kompeten,” imbuhnya.</p><p>&nbsp;</p><p>Tanzania merupakan negara kedua di Afrika yang memiliki populasi hewan ternak terbanyak setelah Ethiopia. Industri kulit memiliki potensi besar karena banyaknya kulit yang tersedia dari populasi hewan ternak yang tinggi tersebut. Akan tetapi, SDM kompeten di industri kulit masih menjadi tantangan tersendiri bagi Tanzania.</p><p>&nbsp;</p><p>“Ini adalah kesempatan untuk meningkatkan kualitas produk kulit di Tanzania. Pelatihan ini merupakan hal yang penting untuk membantu menghadapi tantangan SDM industri kulit kami," ujar Staf Kementerian Industri dan Perdagangan Tanzania, Lugano Wilson.</p><p>&nbsp;</p><p>Maria Renata Hutagalung, Direktur Kerja Sama Pembangunan Internasional Kementerian Luar Negeri, turut melihat potensi industri kulit di Tanzania. "Menurut laporan FAO pada 2020, aktivitas peternakan berkontribusi 7,6 persen terhadap Produk Domestik Bruto (PDB) Tanzania. Banyaknya hewan ternak dan tersedianya SDM yang memadai dapat menjadi keuntungan bagi Tanzania untuk memenuhi permintaan kulit dan produk kulit secara domestik, nasional, dan internasional.”</p><p>&nbsp;</p><p>Pelatihan yang dilakukan terfokus pada penyamakan kulit yang merupakan pelatihan pendahuluan secara daring. Untuk mendapatkan kompetensi menyeluruh, akan diadakan pelatihan luring atau <i>offline</i> untuk enam peserta dari Tanzania yang dilakukan di Politeknik ATK Yogyakarta.</p><p>&nbsp;</p><p>Noviyanti, Kepala Biro Kerja Sama Teknik Luar Negeri Kementerian Sekretariat Negara, mengungkapkan apresiasi kepada pihak-pihak yang terlibat. “Saya mengucapkan terima kasih kepada seluruh pihak yang terlibat, yaitu Kementerian Luar Negeri, Kementerian Perindustrian, Politeknik ATK Yogyakarta, GIZ Jerman, serta pemerintah Tanzania dalam terselenggaranya kegiatan ini.”</p><p>&nbsp;</p><p>“Kami berharap program ini akan memperkuat hubungan antara kedua negara. Kami juga berharap pelatihan dapat membantu mengembangkan industri pemrosesan kulit di Tanzania melalui SDM yang kompeten," pungkas Restu.</p><p>Demikian Siaran Pers ini untuk disebarluaskan.</p><p><br>&nbsp;</p>', 'kinerja-mulus-industri-kulit-nasional-tanzania-belajar-dari-indonesia', 'https://api.demoserver.id/media/uploads/f25f66bf0eb54578a1a2db275ce93913.jpeg', 'PUBLISH', '2022-11-06', '2022-11-06 17:00:00', NULL, NULL),
  (193, 'news', 'Hasilkan Produk Lokal Unggulan, Kemenperin Fokus Kembangkan Sentra IKM', '<p>Kementerian Perindustrian fokus mengembangkan sentra industri kecil dan menengah di Tanah Air. Upaya strategis ini untuk memperkuat struktur industri nasional, membuka kesempatan kerja, serta meningkatkan nilai ekspor.</p><p><br>“Untuk mewujudkan hal tersebut, Kementerian Perindustrian melalui Direktorat Jenderal Industri Kecil, Menengah dan Aneka (IKMA) semakin memperkuat kapasitas kelembagaan, serta pemberian fasilitas di sentra-sentra IKM agar daya saingnya meningkat,” kata Direktur Jenderal IKMA Kemenperin, Reni Yanita di Lampung, Rabu (26/10).<br>&nbsp;</p><p>Dirjen IKMA menjelaskan, keberadaan sentra IKM mampu membangun <i>sharing knowledge</i> antar pelaku IKM sekaligus penguatan <i>branding</i> dan <i>marketing</i> bagi produk yang dihasilkan oleh IKM. “Pembinaan yang diberikan kepada sentra IKM ini diharapkan dapat meningkatkan kompetensi SDM, meningkatkan mutu produksi dan menjamin hasil akhir produk IKM yang dihasilkan,” tuturnya.<br>&nbsp;</p><p>Menurut Reni, pengembangan sentra IKM diatur dalam Peraturan Pemerintah Nomor 29 Tahun 2018 tentang Pemberdayaan Industri. Pada PP 29/2018 ini disebutkan, sentra IKM merupakan sekelompok IKM dalam satu lokasi atau tempat yang terdiri atas paling sedikit lima unit usaha yang menghasilkan produk sejenis, menggunakan bahan baku sejenis dan/atau melakukan proses produksi yang sama.<br>&nbsp;</p><p>“Di dalam sentra IKM, terdapat pengurus, pengelola, anggota, dan unit pelayanan teknis sentra,” ujarnya. Keberadaan sentra IKM dinilai berperan penting dalam upaya penyebaran dan pemerataan jumlah IKM di seluruh Indonesia.</p><p>&nbsp;</p><p>Direktori Sentra Industri Indonesia tahun 2020, yang diterbitkan oleh Badan Pusat Statisik menyebutkan jumlah sentra IKM di Indonesia mencapai 13.762, dengan total unit usaha mencapai 516.124 unit.<br>&nbsp;</p><p>“Sentra industri ini mencakup batasan wilayah desa, dan memenuhi kriteria berupa adanya organisasi atau pembinaan dari kementerian/dinas/lembaga, dikenal masyarakat, dan minimum jumlah usaha sejenis dalam desa adalah 20 persen dari jumlah rumah tangga di desa tersebut,” papar Reni.<br>&nbsp;</p><p>Menurutnya, sentra IKM umumnya menggambarkan lokasi yang memiliki bahan baku dan SDM yang mampu memenuhi proses produksi dalam level industri. Artinya, bahan baku cukup untuk menciptakan produk dengan pertimbangan skala ekonomis tertentu, SDM terampil dalam jumlah yang cukup banyak, dan adanya beberapa IKM berkelompok untuk mengisi rantai nilai produksi tertentu.<br>&nbsp;</p><p>“Fasilitasi pengembangan sentra IKM baik dari pemerintah pusat maupun daerah harus mampu berbuah produk unggulan sentra IKM, baik itu produk OVOP, produk untuk ekspor, kontribusi bagi ketahanan pangan, maupun sebagai <i>supply chain </i>industri besar,” ungkap Reni.</p><p><strong>Revitalisasi sentra IKM</strong></p><p>Reni menambahkan, kegiatan dalam upaya pengembangan sentra IKM dapat bersinergi dengan program lintas kementerian dan lembaga melalui anggaran pusat (APBN), daerah (APBD) seperti Dana Alokasi Khusus (DAK) fisik dan non-fisik bidang IKM.</p><p>“Beberapa kegiatan peningkatan sarana dan prasarana fisik, seperti pembangunan rumah produksi, UPT, rumah kemasan, mesin dan peralatan, dan lain-lain dapat diusulkan oleh daerah sebagai upaya untuk menciptakan keunggulan daya saing produk di sentra IKM tersebut,” sebut Reni.</p><p>&nbsp;</p><p>Sementara itu, DAK fisik bidang IKM terdiri atas dua menu, yaitupembangunan sentra IKM dan revitalisasi sentra IKM. Fasilitas revitalisasi sentra ini misalnya telah digunakan Pemerintah Kota Bandar Lampung untuk membangun sentra IKM tenun tapis di Jalan Teuku Cik Ditiro, Kelurahan Beringin Jaya, Kecamatan Kemiling.<br>&nbsp;</p><p>“Anggaran revitalisasi Gedung Sentra Industri Tenun Tapis Kota Bandar Lampung bersumber dari DAK fisik Kemenperin tahun 2021. Gedung ini merupakan sarana bagi para penenun untuk meningkatkan kapasitas dan kreativitas, serta promosi kain tapis Lampung yang saya harapkan dapat terus menjadi lokasi favorit bagi mereka yang berkecimpung di bidang fesyen berbasis wastra Nusantara,” ungkap Reni.<br>&nbsp;</p><p>Gedung Sentra Industri Tapis Kota Bandar Lampung memiliki fasilitas gedung kantor UPT, kantor pengelola dan administrasi, gedung produksi, gedung pusat promosi, serta mesin dan peralatan dan sejumlah sarana prasarana. Gedung ini dimanfaatkan oleh 15 IKM Tapis di Kota Bandar Lampung.<br>&nbsp;</p><p>“Dengan revitalisasi ini, diharapkan tercipta rumah produksi dengan pengelolaan air limbah yang baik dan mesin peralatan yang mumpuni bagi IKM Tenun Tapis di Kota Bandar Lampung,” ucap Reni.<br>&nbsp;</p><p>Selama ini, tenun tapis memang dikenal sebagai produk khas Lampung yang potensial karena memiliki nilai budaya yang tinggi, dan dapat dikembangkan menjadi beberapa produk turunan, seperti pakaian jadi, tas dan kerajinan lainnya. Peluang dalam hal pemenuhan produksi tersebut harus dimanfaatkan oleh pelaku IKM di Kota Bandar Lampung untuk dapat terus berkembang sehingga produksi tapis IKM dapat membantu meningkatkan pertumbuhan ekonomi daerah.</p><p>&nbsp;</p><p>“Oleh sebab itu, manajemen konsep bisnis yang baik penting dalam industri fesyen lokal,” tandasnya. Apalagi, tren fesyen Indonesia terus berkembang dan patut dilirik oleh masyarakat agar semakin berminat menggunakan produk fesyen dalam negeri.</p><p>&nbsp;</p><p>Pemerintah Pusat maupun Daerah sebagai Pembina IKM harus peka dalam menyikapi hal tersebut, tidak hanya fokus pada peningkatan kualitas produk, namun juga harus memiliki sebuah konsep proses bisnis yang baik. Selain itu, fasilitasi kemitraan dengan industri besar maupun sektor ekonomi lain juga penting untuk mencapai bisnis IKM yang mandiri berkelanjutan.<br>&nbsp;</p><p>Reni berharap revitalisasi Gedung Sentra Industri Tapis tidak hanya mempercantik bangunan semata, tetapi menghasilkan pengelolaan yang cakap. “Ada komunitas yang terbentuk, ada desain-desain yang berkembang dan dikreasikan sehingga Sentra Industri Tapis dapat berkontribusi dalam meningkatkan kesejahteraan para penenun dan masyarakat sekitarnya,” paparnya.</p><p>&nbsp;</p><p>Demikian Siaran Pers ini untuk disebarluaskan.</p>', 'hasilkan-produk-lokal-unggulan-kemenperin-fokus-kembangkan-sentra-ikm', 'https://api.demoserver.id/media/uploads/d704a086a69646a085d79499e12c4480.jpeg', 'PUBLISH', '2022-11-07', '2022-11-07 12:53:13', NULL, NULL),
  (194, 'news', 'Kemenperin Pastikan Industri Farmasi Uji Bahan Baku Obat dan Implementasikan Sistem Manajemen Mutu', '<p>Kementerian Perindustrian (Kemenperin) mendorong industri farmasi untuk selalu mendukung kesehatan masyarakat dengan menyediakan produk-produk obat yang aman, berkhasiat, dan bermutu. Menindaklanjuti arahan Presiden Joko Widodo mengenai pengawasan produksi obat, khususnya terkait dengan kejadian cemaran Etilen glikol (EG) dan Dietilen glikol (DEG) yang melebihi ambang batas pada obat sirup, Kemenperin bekerja sama dengan Badan Pengawas Obat dan Makanan (BPOM), Kementerian Kesehatan, dan seluruh industri farmasi untuk bersama-sama memastikan mutu berlaku atas seluruh produk, mulai dari bahan baku hingga produk jadi, sesuai dengan ketentuan yang berlaku.</p><p><br>&nbsp;</p><p>Kemenperin terus mengimbau industri farmasi untuk menggunakan bahan baku yang sesuai dengan regulasi serta melakukan monitoring dan evaluasi secara berkala baik bersama-sama dengan Badan POM maupun pengujian secara independen. “Sehingga produk yang didistribusikan, mutu dan kualitasnya terjamin dan aman untuk dikonsumsi oleh masyarakat,” kata Menteri Perindustrian Agus Gumiwang Kartasasmita, Rabu (26/10).</p><p><br>&nbsp;</p><p>Untuk memastikan keamanan produk obat-obatan, Kemenperin meminta perusahaan untuk melakukan uji laboratorium terhadap parameter kritis seperti persyaratan cemaran pada bahan baku obat yang digunakan, sesuai dengan Farmakope Indonesia atau standar mutu lainnya yang berlaku. “Kami juga memastikan perusahaan mengimplementasikan sistem manajemen kualitas di industri farmasi berjalan guna menjamin produk yang dihasilkan memenuhi syarat quality, safety dan efficacy sesuai dengan regulasi yang berlaku,” jelas Menperin. Hal ini bertujuan untuk mengeksplorasi seluruh faktor risiko penyebab gagal ginjal, baik dari sumber obat-obatan maupun potensi penyebab lainnya.</p><p><br>&nbsp;</p><p>Hingga saat ini, Kemenperin telah melakukan koordinasi secara langsung dengan mengunjungi beberapa fasilitas produksi industri farmasi untuk memastikan bahwa fasilitas produksi yang dimiliki oleh perusahaan industri telah memenuhi persyaratan Cara Pembuatan Obat yang Baik (CPOB), serta produknya terdaftar dan memiliki Nomor Izin Edar (NIE). “Pengecekan ke fasilitas produksi dilakukan untuk memastikan bahwa industri tidak menggunakan EG dan DEG sebagai bahan baku tambahan dalam sirop obat,” ujar Plt. Direktur Jenderal Industri Kimia, Farmasi, dan Tekstil Kemenperin Ignatius Warsito.</p><p><br>&nbsp;</p><p>Kemenperin memastikan bahwa industri menghentikan proses produksi, distribusi dan recall terhadap seluruh batch produk yang berdasarkan hasil pengujian diduga mengandung cemaran EG/DEG di atas ambang batas. “Industri telah melakukan karantina terhadap seluruh produk sirop obat maupun bahan baku PEG, PG, sorbitol, dan gliserin/gliserol yang ada di gudang pada fasilitas produksi,” imbuhnya.</p><p><br>&nbsp;</p><p>Kemenperin juga memastikan bahwa industri memiliki tim khusus yang menangani laporan/keluhan pelanggan terhadap produknya serta melakukan farmakovigilans untuk memantau efek samping dari obat yang diproduksi.</p><p><br>&nbsp;</p><p>Demikian Siaran Pers ini untuk disebarluaskan.</p>', 'kemenperin-pastikan-industri-farmasi-uji-bahan-baku-obat-dan-implementasikan-sistem-manajemen-mutu', 'https://api.demoserver.id/media/uploads/a863fa46b0af45f0b3836da59a2a5b6b.jpeg', 'PUBLISH', '2022-11-06', '2022-11-06 17:00:00', NULL, NULL),
  (195, 'news', 'Corporate University Jadi Jurus Kemenperin Cetak SDM Berdaya Saing Global', '<p>Keberadaan sumber daya manusia (SDM) yang kompeten dan berdaya saing merupakan salah satu kunci utama meningkatkan produktivitas dan kinerja industri manufaktur. Dalam hal ini, lembaga pendidikan vokasi memiliki peran penting untuk menghasilkan SDM industri yang terampil sesuai dengan orientasi kebutuhan pasar saat ini.</p><p><br>&nbsp;</p><p>&nbsp;</p><p><br>&nbsp;</p><p>“Guna mencapai tersebut, Kementerian Perindustrian telah menetapkan kebijakan Corporate University yang tertuang dalam Keputusan Menteri Perindustrian Nomor 1009 Tahun 2021, dengan visi dan misi politeknik dan akademi komunitas di lingkungan Kemenperin menjadi penyelenggara pendidikan vokasi industri yang <i>excellence</i> dan berdaya saing global,” kata Kepala Badan Pengembangan Sumber Daya Manusia Industri (BPSDMI) Kemenperin, Arus Gunawan di Jakarta, Selasa (25/10).</p><p><br>&nbsp;</p><p>&nbsp;</p><p><br>&nbsp;</p><p>Arus menjelaskan, kebijakan Corporate University sebagai bentuk antisipasi dalam upaya menyelesaikan permasalahan vokasi nasional saat ini, antara lain kurikulum yang masih belum selaras dengan kebutuhan industri, industri yang belum mendapat pasokan SDM dari jurusan yang sesuai dengan kebutuhan, kondisi sarana dan prasarana pendidikan vokasi yang masih belum memadai, serta daya serap lulusan pendidikan vokasi di dunia industri yang masih rendah.</p><p><br>&nbsp;</p><p>&nbsp;</p><p><br>&nbsp;</p><p>“Dari permasalahan vokasi nasional yang sedang kita hadapi, Kemenperin sangat menyadari bahwa membangun pendidikan vokasi yang sesuai dengan kebutuhan dunia industri tidak lah mudah, kita harus melakukan penyusunan standard sebagai acuan pembelajaran,” ungkapnya.</p><p><br>&nbsp;</p><p>&nbsp;</p><p><br>&nbsp;</p><p>Upaya lainnya adalah membangun kurikulum sesuai kebutuhan dunia industri, menyediakan dosen yang profesional, menyediakan sarana dan prasaran sesuai dengan standard industri, serta melakukan sertifikasi kompetensi bagi para lulusannya. “Ini merupakan rangkaian yang harus terus di lakukan bersama-sama dengan industri. Sebab, kunci keberhasilan penyelenggaraan pendidikan vokasi adalah kerja sama dengan industri dalam mencetak lulusan yang langsung dapat bekerja di industri,” imbuhnya.</p><p><br>&nbsp;</p><p>&nbsp;</p><p><br>&nbsp;</p><p>Oleh karena itu, seluruh unit pendidikan Kemenperin agar senantiasa melibatkan pelaku usaha, industri dan asosiasi mulai dari perencanaan, penyusunan kurikulum, kegiatan pengajaran, kegiatan praktek kerja industri, hingga penyerapan lulusan.</p><p><br>&nbsp;</p><p>&nbsp;</p><p><br>&nbsp;</p><p>Kepala BPSDMI menegaskan, seluruh unit pendidikan vokasi di lingkungan Kemenperin juga agar dapat membangun profesionalitas dan kemandirian dalam rangka mengelola lembaga pendidikan. “Semua unit pendidikan vokasi di lingkungan Kemenperin adalah unit pendidikan yang lahir secara spesifik dan teknis,” terangnya.</p><p><br>&nbsp;</p><p>&nbsp;</p><p><br>&nbsp;</p><p>Salah satu unit pendidikan Kemenperin yang menjadi unggulan adalah Politeknik AKA Bogor. Kampus yang berdiri sejak tahun 1959 dengan nama Akademi Kimia Analisis (AKA) ini memiliki tiga program studi level D-III, yaitu Analisis Kimia, Penjaminan Mutu Industri Pangan, dan Pengolahan Limbah Industri. Selain itu sudah terdapat program studi Nanoteknologi Pangan untuk tingkat sarjana terapan atau D-IV.</p><p><br>&nbsp;</p><p>&nbsp;</p><p><br>&nbsp;</p><p>Memiliki angka serapan tenaga kerja yang tinggi, lulusan Politeknik AKA Bogor pada tahun 2021 kini tidak ada yang menganggur dengan 87% terserap di dunia kerja. Dari 398 lulusan tahun 2021, 347 telah bekerja, 13 melanjutkan studi, dan 38 memilih untuk berwirausaha.</p><p><br>&nbsp;</p><p>&nbsp;</p><p><br>&nbsp;</p><p>“Saya harapkan Politeknik AKA Bogor senantiasa menjaga kesesuian penyelenggaraan pendidikan dengan kebutuhan industri.&nbsp; Untuk itu, ayo kita segera berbenah dan mengimplementasikan kebijakan Corporate University dengan bergerak secara cepat untuk mencapai target-target yang telah ditetapkan dan di akhir tahun ini akan saya monitor kembali target dan capaian dari Politeknik AKA Bogor,” pungkasnya.</p><p><br>&nbsp;</p><p>Demikian Siaran Pers ini untuk disebarluaskan.</p><p><br>&nbsp;</p>', 'corporate-university-jadi-jurus-kemenperin-cetak-sdm-berdaya-saing-global', 'https://api.demoserver.id/media/uploads/6156f718cc6d4599a6f9de433235b954.jpeg', 'PUBLISH', '2022-11-07', '2022-11-07 12:56:04', NULL, NULL),
  (196, 'news', 'Naik 54%, Investasi Sektor Manufaktur Lampaui Rp 365 Triliun', '<p>Di tengah kondisi ekonomi dunia yang tidak menentu, Indonesia masih menjadi negara tujuan investasi bagi para pelaku industri manufaktur nasional maupun global. Ini tercermin dari realisasi penanaman modal sektor industri manufaktur yang mencapai Rp365,2 triliun sepanjang Januari-September 2022.</p><p><br>&nbsp;</p><p>&nbsp;</p><p><br>&nbsp;</p><p>“Capaian tersebut meningkat 54% dibanding periode yang sama pada tahun lalu sebesar Rp236,8 triliun. Kepercayaan diri para investor di sektor industri ini harus tetap dijaga, yang didukung dengan berbagai kebijakan strategis,” kata Menteri Perindustrian Agus Gumiwang Kartasasmita, Selasa (25/10).</p><p><br>&nbsp;</p><p>&nbsp;</p><p><br>&nbsp;</p><p>Merujuk data Kementerian Investasi/BKPM, pada Januari-September 2022, sektor industri manufaktur memberikan kontribusi sebesar 40,9 % terhadap total investasi yang mencapai Rp892,4 triliun. Secara kumulatif, investasi di Indonesia tumbuh 35,3 % (<i>y-o-y</i>), dan selama sembilan bulan ini telah berhasil mencapai 74,4% dari target Rp1.200 triliun pada tahun 2022.</p><p><br>&nbsp;</p><p>&nbsp;</p><p><br>&nbsp;</p><p>Sementara itu, penanaman modal dalam negeri (PMDN) di sektor industri manufaktur sebesar Rp104,9 triliun. Adapun subsektor yang memberikan andil paling besar adalah industri makanan senilai Rp38 triliun atau menyumbang 9,2% dari total realisasi PMDN yang mencapai Rp413,1 triliun.</p><p><br>&nbsp;</p><p>&nbsp;</p><p><br>&nbsp;</p><p>Sedangkan, penanaman modal asing (PMA) di sektor industri manufaktur menembus Rp260,3 triliun. Subsektor yang menyokong paling besar adalah industri logam dasar, barang logam, bukan mesin, dan peralatannya hingga menyentuh USD8,5 miliar atau berkontribusi 25,3% dari seluruh realisasi PMA yang berada di angka Rp479,3 triliun.</p><p><br>&nbsp;</p><p>&nbsp;</p><p><br>&nbsp;</p><p>“Di tengah situasi dunia saat ini yang dilanda krisis pangan, energi, hingga finansial, semua negara sedang berlomba-lomba berebut investasi. Alasannya, karena dengan investasi ini ada peningkatan nilai tambah, penciptaan lapangan kerja, dan peningkatan devisa,” papar Menperin.</p><p><br>&nbsp;</p><p>&nbsp;</p><p><br>&nbsp;</p><p>Oleh karenanya, pemerintah fokus untuk menciptakan iklim usaha dan investasi yang kondusif dengan menjaga stabilitas ekonomi dan politik yang baik di dalam negeri. “Apalagi, berbagai indikator penting pembangunan terus menunjukkan perbaikan, dan ini menandakan optimisme bagi kita semua untuk melakukan percepatan pemulihan dan pertumbuhan sehingga mampu menuju transformasi ekonomi yang inklusif dan berkelanjutan,” imbuh Agus.</p><p><br>&nbsp;</p><p>&nbsp;</p><p><br>&nbsp;</p><p>Lebih lanjut, sesuai arahan Presiden Joko Widodo, hilirisasi industri menjadi salah satu kunci kemajuan perekonomian Indonesia. Sebab, kebijakan hilirisasi akan berkontribusi signifikan terhadap pemasukan negara melalui pajak ekspor, royalti, pendapatan negara bukan pajak (PNBP), dan dividen.</p><p><br>&nbsp;</p><p>&nbsp;</p><p><br>&nbsp;</p><p>“Seperti yang Bapak Presiden sering kali sampaikan, hilirisasi industri menjadi prioritas nomor satu. Sebagai gambaran, saat masih diekspor dalam bentuk bahan mentah, kontribusi komoditas nikel nilainya sekitar Rp15 triliun dalam setahun. Setelah masuk ke industrialisasi, nilainya melompat tajam menjadi USD20,9 miliar atau setara Rp360 triliun,” jelas Menperin.</p><p><br>&nbsp;</p><p>&nbsp;</p><p><br>&nbsp;</p><p>Masih berdasarkan data Kementerian Investasi/BKPM, pada triwulan III tahun 2022, investasi sektor industri logam dasar, barang logam, bukan mesin, dan peralatannya mencapai Rp44 triliun. Angka ini memberikan kontribusi paling tinggi (14,3%) terhadap realisasi total investasi di triwulan III-2022 sebesar Rp307,8 triliun.</p><p><br>&nbsp;</p><p>&nbsp;</p><p><br>&nbsp;</p><p>“Kami meyakini peningkatan investasi di sektor tersebut berkorelasi dengan kebijakan pemerintah dalam memacu hilirisasi industri, khususnya sektor pertambangan. Artinya, pemerintah sangat konsisten sekali bahwa realisasi investasi tidak hanya didorong oleh sektor jasa, tetapi sudah membangun industri hilirnya sehingga memperdalam struktur manufaktur kita agar bisa lebih berdaya saing,” pungkasnya.</p><p><br>&nbsp;</p><p>Demikian Siaran Pers ini untuk disebarluaskan.</p>', 'naik-54percent-investasi-sektor-manufaktur-lampaui-rp-365-triliun', 'https://api.demoserver.id/media/uploads/9397bdc6e3fb4f7098c6b791652facf6.jpeg', 'PUBLISH', '2022-11-07', '2022-11-07 12:56:52', NULL, NULL),
  (197, 'news', 'Transaksi Paviliun Indonesia di Pameran SIAL Paris 2022 Tembus USD 33,5 Juta', '', 'transaksi-paviliun-indonesia-di-pameran-sial-paris-2022-tembus-usd-335-juta', 'https://api.demoserver.id/media/uploads/c3e52887812945adb8a87cf0acbe0911.png', 'PUBLISH', '2022-11-07', '2022-11-07 12:58:30', NULL, NULL),
  (198, 'news', 'Kemenperin Pacu IKM Permesinan Tembus Pasar Ekspor', '<p>Kementerian Perindustrian aktif memfasilitasi pelaku industri kecil dan menengah (IKM) untuk ikut serta dalam pameran berskala internasional. Tujuannya agar membuka akses IKM bisa tembus ke pasar global atau ekspor sehingga dapat memberikan kontribusi bagi perekonomian nasional.</p><p><br>&nbsp;</p><p>&nbsp;</p><p><br>&nbsp;</p><p>“Keikutsertaan IKM di pameran internasional menjadi kesempatan besar bagi mereka untuk mampu mempelajari langsung strategi dalam menembus atau memperluas pasar ekspornya,” kata Menteri Perindustrian Agus Gumiwang Kartasasmita di Jakarta, Sabtu (22/10).</p><p><br>&nbsp;</p><p>&nbsp;</p><p><br>&nbsp;</p><p>Oleh karena itu, pelaku IKM perlu mengetahui selera dan kebutuhan konsumen luar negeri, standar kualitas produk, dan persyaratan legalitas ekspor. “Dengan mereka ikut dalam pameran internasional, akan bisa memperluas jejaring komunikasi bisnis dengan para calon pembeli dan investor,” ujar Agus.</p><p><br>&nbsp;</p><p>&nbsp;</p><p><br>&nbsp;</p><p>Pada 19-21 Oktober 2022, Kemenperin melalui Direktorat Jenderal Industri Kecil, Menengah dan Aneka (IKMA) memboyong enam IKM permesinan untuk memajang karya produksinya di Pameran Inagritech (<i>Indonesia Agricultural Machinery, Equipment, Technology &amp; Services Exhibition) </i>2022 yang digelar di JI-Expo Kemayoran, Jakarta<i>.</i></p><p><br>&nbsp;</p><p>&nbsp;</p><p><br>&nbsp;</p><p>Inagritech merupakan pameran inovasi teknologi di bidang agrikultur terbesar di Indonesia, bahkan ASEAN, yang diikuti oleh ratusan perusahaan dari 22 negara dan ribuan pengunjung. Pada Inagritech 2019, tercatat 8.616 pengunjung pameran dari 20 negara dan terbukti mampu menggenjot penjualan para eksibitor.</p><p><br>&nbsp;</p><p>&nbsp;</p><p><br>&nbsp;</p><p>“Pameran inovasi agrikultur ini penting untuk mengembangkan kemampuan IKM agar bisa berpacu menunjang industri pertanian dan perkebunan tanah air, di tengah isu krisis pangan dunia. Dengan inovasi dan teknologi ini, kita harus bisa menciptakan beragam alternatif pangan yang berkelanjutan agar ketahanan pangan bisa terwujud,” papar Menperin.</p><p><br>&nbsp;</p><p>&nbsp;</p><p><br>&nbsp;</p><p><strong>Difasilitasi Kemenperin</strong></p><p><br>&nbsp;</p><p>Dari 52 partisipan asal Indonesia yang tampil di Inagritech 2022, enam IKM permesinan yang difasilitasi Kemenperin ikut dalam pameran ini, yaitu Cahaya Agro Teknik, Hinoka Alsindo Teknik, Rumah Mesin, Indotech Trimitra Abadi, Inamas Sintesis Teknologi (Inastek), dan Willindo Jaya Utama.</p><p><br>&nbsp;</p><p>&nbsp;</p><p><br>&nbsp;</p><p>PT Hinoka Alsindo Teknik memproduksi mesin pengolahan makanan dan minuman seperti mesin sangrai kopi, serta alat dan mesin di bidang pertanian, perkebunan dan aneka mesin bagi IKM. Di JI-Expo, Hinoka akan memamerkan <i>roaster</i> kopi, <i>huller</i> kopi, dan mesin APPO. Hinoka merupakan IKM binaan Ditjen IKMA yang pernah mendapatkan fasilitas restrukturisasi mesin/peralatan IKM tahun 2020, serta mengikuti pameran virtual Festival Virtual Bangga Mesin Buatan Indonesia 2020 dan 2021.</p><p><br>&nbsp;</p><p>&nbsp;</p><p><br>&nbsp;</p><p>Dirjen IKMA Kemenperin Reni Yanita mengungkapkan, IKM permesinan binaan Ditjen IKMA terbukti telah mampu menyuplai teknologi buatannya ke mancanegara, seperti yang dilakukan oleh PT Cahaya Agro Teknik. Di Inagritech, Cahaya Agro Teknik akan memamerkan mesin kupas pala dan kemiri, mesin peras santan serta mesin peras biji-bijian.</p><p><br>&nbsp;</p><p>&nbsp;</p><p><br>&nbsp;</p><p>“Cahaya Agro Teknik telah mendapatkan fasilitasi sertifikasi Manajemen Mutu ISO 9001:2015 pada tahun ini dan fasilitasi pada pameran virtual Festival Virtual Bangga Mesin Buatan Indonesia 2021. IKM tersebut juga telah berhasil mengekspor produknya ke Timor Leste, Papua Nugini, Malaysia, Arab Saudi, Paris, German, India, dan Nigeria,” ungkap Reni.</p><p><br>&nbsp;</p><p>&nbsp;</p><p><br>&nbsp;</p><p>Berikutnya, CV Rumah Mesin juga turut mendapatkan fasilitasi bimbingan dan pendampingan dari Ditjen IKMA, berupa bimbingan teknis penerapan teknologi industri 4.0 bagi IKM permesinan dan pendampingan otomasi mesin oven gula semut bagi IKM permesinan teknologi tepat guna pada tahun 2020. Selain itu, Rumah Mesin juga menjadi eksibitor pada Festival Virtual Bangga Mesin Buatan Indonesia tahun 2020 dan 2021.</p><p><br>&nbsp;</p><p>&nbsp;</p><p><br>&nbsp;</p><p>Rumah Mesin yang merupakan distributor pusat mesin sekaligus produsen mesin pengolahan makanan, minuman, pertanian dan perkebunan, akan membawa mesin pencetak pelet, mesin spinner/pengering, mesin pemarut, mesin pengupas sorgum, dan mesin perajang porang untuk dipamerkan di Inagritech 2022.</p><p><br>&nbsp;</p><p>&nbsp;</p><p><br>&nbsp;</p><p>“Pada November 2021, satu unit pemarut kelapa buatan Rumah Mesin telah mengantongi sertifikat Standar Nasional Indonesia (SNI), setelah menjalani tes di Balai Besar Pengembangan Mekanisasi Pertanian. Hasil uji ini membuktikan bahwa mesin buatan Rumah Mesin diciptakan dengan ketelitian yang sesuai dengan standar nasional,” papar Reni.</p><p><br>&nbsp;</p><p>&nbsp;</p><p><br>&nbsp;</p><p>Sementara itu, PT Inamas Sintesis Teknologi (Inastek) akan memboyong <i>showcase indoor farming</i> dan <i>vertical garden </i>yang keduanya telah mendapatkan sertifikat Hak Cipta untuk <i>controller </i>dan aplikasinya.</p><p><br>&nbsp;</p><p>&nbsp;</p><p><br>&nbsp;</p><p>Sedangkan PT Indotech Trimitra Abadi akan memamerkan <i>roaster </i>kopi Pratter 5.0. “Produk Indotech telah diekspor ke Malaysia,” sebut Reni. Sebelumnya, perusahaan ini mendapatkan fasilitas restrukturisasi mesin/peralatan IKM, fasilitasi sertifikasi TKDN, dan pendampingan <i>test report </i>pada<i> </i>tahun 2020, serta <i>workshop </i>dan pendampingan <i>machinery SME Go Export, </i>dan pendampingan sertifikasi ISO IKM logam di tahun 2022.</p><p><br>&nbsp;</p><p>&nbsp;</p><p><br>&nbsp;</p><p>Adapun IKM Willindo Jaya Utama, akan memamerkan mesin mini <i>roaster</i>. IKM ini pernah mengekspor ke Asia Tenggara dan Eropa.&nbsp; Reni mengungkapkan, selain memboyong IKM ke pameran internasional, Ditjen IKMA juga berkomitmen mendorong peningkatan kualitas produk IKM melalui program restrukturisasi mesin peralatan dan fasilitasi standardisasi/sertifikasi.</p><p><br>&nbsp;</p><p>&nbsp;</p><p><br>&nbsp;</p><p>“Ditjen IKMA akan terus mendukung peningkatan produktivitas IKM agar semakin banyak produk berkualitas yang bisa diekspor, bahkan hingga IKM bisa melakukan ekspor sendiri. Upaya ini untuk mendukung target Presiden Joko Widodo untuk terus mendorong surplus neraca perdagangan pada masa mendatang,” pungkas Reni.</p><p><br>&nbsp;</p><p>Demikian Siaran Pers ini untuk disebarluaskan.</p>', 'kemenperin-pacu-ikm-permesinan-tembus-pasar-ekspor', 'https://api.demoserver.id/media/uploads/deedd844f7804077821dbb34ea5431a9.jpeg', 'PUBLISH', '2022-11-07', '2022-11-07 12:59:38', NULL, NULL),
  (199, 'news', 'Jaring Industri Halal Berkualitas, Kemenperin Sosialisasikan IHYA 2022', '<p>Kementerian Perindustrian (Kemenperin) terus berupaya menumbuhkan dan mengembangkan industri halal di Indonesia.&nbsp; Hal ini seiring dengan ekonomi syariah yang tumbuh semakin kokoh, terutama dengan adanya beberapa pendorong utama, yaitu besarnya populasi Muslim, meningkatnya kesadaran terhadap nilai-nilai etika Islam yang berkaitan dengan konsumsi produk halal dan thoyyib, dan semakin banyak strategi dan program nasional yang didedikasikan untuk pengembangan produk dan layanan halal.</p><p>Dengan populasi umat muslim sebanyak 229,6 juta jiwa (tahun 2020), Indonesia memiliki potensi pasar halal yang sangat besar. Pengeluaran umat muslim Indonesia untuk produk dan layanan halal mencapai USD184 miliar pada tahun 2020 dan diproyeksikan meningkat sebesar 14,96% (USD281,6 miliar) pada tahun 2025. Jumlah tersebut setara dengan 11,34% pengeluaran halal global, menjadikan Indonesia sebagai konsumen pasar halal terbesar di dunia. Namun hal ini juga menarik perhatian negara-negara lain yang turut menjadikan Indonesia sebagai target utama pasar produk halal mereka.</p><p>“Untuk menggairahkan ekosistem industri halal nasional, Kemenperin memberikan apresiasi kepada para Pemangku Kepentingan Industri Halal yang mendukung dan berperan aktif dalam penumbuhan, pengembangan, dan pemberdayaan Industri Halal nasional melalui Indonesia Halal Industry Awards (IHYA), yang telah kami mulai sejak tahun 2021 yang lalu,” jelas Kepala Pusat Pemberdayaan Industri Halal (PPIH) Kemenperin Junadi Marki dalam Sosialisasi IHYA 2022 di Padang, Kamis (20/10).</p><p>Dengan kembali menggelar IHYA di tahun 2022, Kemenperin menargetkan kontribusi pada penguatan ekosistem ekonomi syariah, khususnya industri halal. IHYA juga diharapkan dapat menjadi brand untuk kemajuan sektor industri halal Indonesia, sekaligus menjadi representasi Visi Indonesia sebagai pusat produsen halal terkemuka di dunia. Ajang ini juga bertujuan mendorong para pelaku industri halal nasional untuk lebih termotivasi melakukan inovasi-inovasi dalam menumbuhkan, mengembangkan, dan memberdayakan industri halal di Indonesia.</p><p>“Kami juga kembali melibatkan pemangku kepentingan dari kalangan lembaga pemerintah, non pemerintah, organisasi kemasyarakatan (Ormas), asosiasi dan akademisi, mulai dari tahapan penyusunan kategori dan aspek serta kriteria penilaian, hingga rangkaian penilaian dan penetapan pemenang,” jelas Junadi.</p><p>Proses penilaian akan dilakukan oleh Tim Penilai IHYA yang akan diketuai oleh Sekretaris Jenderal Kemenperin Dody Widodo, yang sekaligus merangkap sebagai Ketua Dewan Pertimbangan. Tim penilai sendiri terdiri dari tim teknis, dewan juri, dan dewan pertimbangan. “Tim penilai IHYA berasal dari perwakilan unit kerja di Kementerian Perindustrian, perwakilan dari kementerian/lembaga terkait, pimpinan asosiasi industri, organisasi kemasyarakatan, akademisi, serta pemangku kepentingan halal terkait lainnya,” imbuh Kepala PPIH.</p><p>Untuk mempersiapkan pelaksanaan IHYA 2022, penyelenggara telah membangun sistem informasi untuk pendaftaran dan penilaian peserta, sehingga semua rangkaian kegiatan mulai dari pendaftaran peserta hingga penilaian akan dilakukan secara online melalui portal resmi IHYA, yaitu ihya.kemenperin.go.id.&nbsp;</p><p>Demikian Siaran Pers ini untuk disebarluaskan.</p>', 'jaring-industri-halal-berkualitas-kemenperin-sosialisasikan-ihya-2022', 'https://api.demoserver.id/media/uploads/56bb1e07b118443f9ac30383b5606916.jpeg', 'PUBLISH', '2022-11-07', '2022-11-07 13:00:33', NULL, NULL),
  (200, 'news', 'Kemenperin Pastikan Industri Farmasi Berkomitmen Produksi Obat Berkualitas dan Sesuai Standar', '<p>Kementerian Perindustrian (Kemenperin) menegaskan bahwa setiap produk obat yang dihasilkan oleh industri farmasi dalam negeri sudah mengikuti standar Cara Pembuatan Obat yang Baik (CPOB) dan memenuhi persyaratan mutu sesuai Farmakope Indonesia atau kompendial lainnya.</p><p><br>&nbsp;</p><p>&nbsp;</p><p><br>&nbsp;</p><p>“Kasus ditemukannya Etilen glikol (EG) dan Dietilen glikol (DEG) yang melebihi ambang batas pada obat sirup merupakan kejadian yang tidak diharapkan oleh industri farmasi. Namun Kemenperin terus mendorong perusahaan-perusahaan industri farmasi untuk terus melakukan monitoring dan evaluasi terhadap produk-produk yang dihasilkannya, dan terus memantau perkembangan informasi dari Kementerian dan Lembaga terkait,” kata Menteri Perindustrian Agus Gumiwang Kartasasmita di Jakarta, Jumat (21/10).</p><p><br>&nbsp;</p><p>&nbsp;</p><p><br>&nbsp;</p><p>Dari hasil investigasi Badan Pengawas Obat dan Makanan (BPOM), ditengarai bahwa kedua zat tersebut merupakan cemaran dan bukan sebagai bahan baku tambahan yang digunakan pada formulasi dan proses produksi obat sirup. Cemaran tersebut diduga berasal dari empat bahan baku tambahan, yaitu propilen glikol, polietillen glikol, sorbitol, dan gliserin/gliserol.</p><p><br>&nbsp;</p><p>&nbsp;</p><p><br>&nbsp;</p><p>Menurut Kemenperin, keempat bahan di atas bukan merupakan bahan yang berbahaya atau dilarang penggunaannya dalam pembuatan sirup obat dan telah digunakan sejak lama. Dari keempat bahan tambahan tersebut, baru dua yang sudah dapat diproduksi dalam negeri yaitu sorbitol dengan kapasitas 154.000 ton per tahun, dan gliserin sebesar 883.700 ton per tahun. Sementara untuk propilen glikol dan polietilen glikol masih belum dapat diproduksi dalam negeri dan harus dilakukan impor.</p><p><br>&nbsp;</p><p>&nbsp;</p><p><br>&nbsp;</p><p>Menindaklanjuti perkembangan ini, Kemenperin telah melakukan koordinasi dengan industri farmasi yang produknya mengandung cemaran EG dan DEG melewati ambang batas aman. Industri menyatakan bahwa tidak ada penggunaan bahan baku EG maupun DEG pada proses produksi, sehingga adanya EG dan DEG diduga berasal dari cemaran bahan baku tambahan lain yang disebutkan di atas.</p><p><br>&nbsp;</p><p>“Sebagai tindak lanjutnya, industri terus melakukan evalusi internal, pengujian kandungan cemaran bahan baku pada laboratorium independen, serta berkoordinasi untuk melakukan penarikan produk dari pasar. Hal ini sejalan dengan komitmen industri farmasi untuk memproduksi produk obat yang aman, berkasiat, dan bermutu,” jelas Menperin.</p><p><br>&nbsp;</p><p>Demikian Siaran Pers ini untuk disebarluaskan.</p>', 'kemenperin-pastikan-industri-farmasi-berkomitmen-produksi-obat-berkualitas-dan-sesuai-standar', 'https://api.demoserver.id/media/uploads/73a683c1f7e84368b0fa6acca9b3cfe7.jpeg', 'PUBLISH', '2022-11-07', '2022-11-07 13:01:14', NULL, NULL),
  (201, 'infographic', 'Poster Fasilitas Fiskal dan Non Fiskal KEK', '<p>-</p>', 'poster-fasilitas-fiskal-dan-non-fiskal-kek', 'https://api.demoserver.id/media/uploads/9f633525fef3417b8f5e1ac4b22120d6.jpeg', 'PUBLISH', '2022-11-09', '2022-11-09 17:58:37', NULL, NULL),
  (203, 'infographic', 'Poster KEK Industri', '<p>Kawasan Ekonomi Khusus (KEK) di Indonesia memiliki landasan hukum utama pada Undang-Undang Nomor 39 Tahun 2009, yang mengatur tujuan, fungsi, kawasan, serta mekanisme penyelenggaraan KEK. Undang-undang ini menjadi dasar bagi pemerintah untuk menetapkan area tertentu sebagai pusat kegiatan ekonomi yang memiliki fasilitas dan kemudahan khusus. Ketentuan ini kemudian diperkuat melalui sejumlah peraturan turunan, termasuk PP 1/2020 tentang Penyelenggaraan KEK dan PP 12/2020 tentang Fasilitas dan Kemudahan KEK, yang mengatur lebih rinci proses penetapan, pembangunan, dan insentif fiskal maupun nonfiskal bagi pelaku usaha.</p><p>Penyelenggaraan KEK juga didukung oleh kelembagaan khusus yang diatur dalam Perpres 8/2022, yang menetapkan struktur Dewan Nasional KEK, Dewan Kawasan, dan Administrator di masing-masing KEK. Reformasi regulasi melalui UU Cipta Kerja turut menyempurnakan tata kelola KEK, terutama dalam aspek perizinan, kemitraan dengan UMKM, serta percepatan penyediaan lahan. Dengan kerangka hukum yang semakin komprehensif ini, pemerintah menargetkan KEK menjadi instrumen utama peningkatan investasi dan hilirisasi industri.</p><p>Dari sisi perkembangan, hingga 2025 Indonesia telah memiliki 22 KEK yang tersebar di berbagai daerah dengan fokus sektor yang beragam, mulai dari industri pengolahan, logistik, energi, hingga pariwisata dan ekonomi digital. Realisasi investasi terus menunjukkan tren positif, dengan nilai kumulatif mencapai ratusan triliun rupiah dan penyerapan tenaga kerja yang semakin meningkat. Beberapa KEK seperti Gresik, Kendal, Sei Mangkei, dan Nongsa mulai menunjukkan dampak strategis terhadap rantai hilirisasi dan penguatan daya saing industri nasional.</p><p>Saat ini Indonesia memiliki 22 Kawasan Ekonomi Khusus (KEK) yang telah ditetapkan dan beroperasi dengan fokus pengembangan yang berbeda sesuai potensi daerahnya. Dari jumlah tersebut, 12 KEK merupakan kawasan berbasis industri, yang dirancang untuk memperkuat hilirisasi sumber daya alam, mempercepat pertumbuhan manufaktur, serta mendukung pengembangan teknologi dan logistik nasional. KEK industri ini menjadi pusat kegiatan produksi bernilai tambah tinggi, mulai dari pengolahan mineral, petrokimia, energi, hingga otomotif dan elektronik, sehingga diharapkan mampu memperkuat rantai pasok nasional serta meningkatkan daya saing ekspor Indonesia.</p><p>Sementara itu, 10 KEK lainnya bergerak di sektor pariwisata dan kesehatan, dan berfokus pada peningkatan daya tarik destinasi wisata berkelas internasional, pengembangan ekosistem hospitality, serta penyediaan layanan kesehatan unggulan. KEK jenis ini tidak hanya mendorong kunjungan wisatawan domestik dan mancanegara, tetapi juga membuka peluang untuk pengembangan medical tourism sebagai sektor baru yang berpotensi tinggi. Dengan dukungan fasilitas khusus, kemudahan investasi, serta integrasi antara pemerintah pusat dan daerah, KEK pariwisata dan kesehatan diharapkan mampu membangkitkan ekonomi lokal serta menciptakan lapangan kerja yang luas.</p><p>Meskipun demikian, perkembangan KEK masih menghadapi tantangan seperti kebutuhan infrastruktur pendukung, kesiapan SDM lokal, integrasi dengan pelabuhan/logistik, serta keselarasan kebijakan pusat dan daerah. Luasan KEK Indonesia juga masih relatif kecil dibandingkan negara lain di ASEAN. Namun dengan penguatan regulasi, akselerasi investasi, dan perluasan sektor prioritas, KEK diharapkan dapat menjadi motor pertumbuhan ekonomi yang lebih inklusif dan berkelanjutan bagi Indonesia.</p>', 'poster-kek-industri', '/upload/53615266-748e-4bec-93b6-342123ebfc6b.jpeg', 'PUBLISH', '2022-11-10', '2022-11-10 00:13:08', NULL, NULL),
  (204, 'news', 'Perkuat Kemandirian Industri Alat Kesehatan, Kemenperin Sosialisasi Ventilator Lokal', '', 'perkuat-kemandirian-industri-alat-kesehatan-kemenperin-sosialisasi-ventilator-lokal', 'https://api.demoserver.id/media/uploads/4aa9dc6963cb436ea8999d2226d9312d.jpeg', 'PUBLISH', '2022-11-10', '2022-11-10 00:15:00', NULL, NULL),
