  (206, 'infographic', '14 Lembaga Sertifikasi Industri Hijau', '<p>Lembaga Sertifikasi yang ditunjuk Kementerian Perindustrian per tahun 2023.</p><ul><li>Balai Besar Standardisasi dan Pelayanan Jasa Industri Selulosa</li><li>Balai Besar Standardisasi dan Pelayanan Jasa Industri Jakarta</li><li>Balai Besar Standardisasi dan Pelayanan Jasa Industri Bahan dan Barang Teknik</li><li>Balai Besar Standardisasi dan Pelayanan Jasa Pencegahan dan Pencemaran Industri</li><li>Balai Besar Standardisasi dan Pelayanan Jasa Industri Kulit, Karet, dan Plastik</li><li>Balai Besar Standardisasi dan Pelayanan Jasa Industri Tekstil</li><li>Balai Besar Standardisasi dan Pelayanan Jasa Industri Keramik dan Mineral Nonlogam</li><li>Balai Besar Standardisasi dan Pelayanan Jasa Industri Palembang</li><li>PT Sucofindo ICS</li><li>PT Integrita Global Sertifikat</li><li>Balai Besar Standardisasi dan Pelayanan Jasa Industri Argo</li><li>Balai Besar Standardisasi dan Pelayanan Jasa Industri Kerajinan dan Batik</li><li>Balai Besar Standardisasi dan Pelayanan Jasa Industri Kimia, Farmasi, dan Kemasan</li><li>Balai Besar Standardisasi dan Pelayanan Jasa Industri Logam dan Mesin</li></ul>', '14-lembaga-sertifikasi-industri-hijau', 'https://imc-api-dev.kemenperin.go.id/dashboard/public/upload/05e59727-c43f-4c2b-9762-ac0406e0eddb.png', 'PUBLISH', '2022-11-08', '2022-11-08 00:00:00', NULL, NULL),
