-- Legacy IMC contents migration seeder
-- Generated by sync:contents-from-mysql --export-sql
-- Target content IDs: publication=5, gallery=3, agenda=4

BEGIN;

CREATE TEMP TABLE _legacy_rows (id int, type text, title text, content text, slug text, thumbnail text, status_content text, publish_date text, event_date text, event_end_date text, category_name text);
CREATE TEMP TABLE _legacy_tags (id int, title text);
CREATE TEMP TABLE _legacy_content_tags (legacy_content_id int, tag_title text);
CREATE TEMP TABLE _legacy_content_files (legacy_content_id int, file_name text, file_url text);
CREATE TEMP TABLE _legacy_content_map (legacy_id int, entity text, detail_id int);




-- resolve categories (publication rows only)
SELECT DISTINCT category_name, true, 'legacy-import', 'legacy-import', now(), now()
FROM _legacy_rows
WHERE category_name IS NOT NULL
AND lower(type) IN ('news', 'artikel', 'jurnal')
AND NOT EXISTS (SELECT 1 FROM ms_kategori_contents k WHERE k.title = _legacy_rows.category_name);

-- resolve tags
SELECT DISTINCT title, true, 'legacy-import', 'legacy-import', now(), now()
FROM _legacy_tags
WHERE NOT EXISTS (SELECT 1 FROM ms_tags t WHERE t.title = _legacy_tags.title);

DO $$
DECLARE
  r _legacy_rows%ROWTYPE;
  v_detail_id int;
  v_kategori_id int;
BEGIN
  FOR r IN SELECT * FROM _legacy_rows ORDER BY id LOOP
    v_detail_id := NULL;
    CASE lower(r.type)
      WHEN 'news', 'artikel', 'jurnal' THEN
        IF EXISTS (SELECT 1 FROM content_detail_publications WHERE slug = r.slug) THEN CONTINUE; END IF;
        SELECT id INTO v_kategori_id FROM ms_kategori_contents WHERE title = r.category_name;
          content_id, title, slug, headline, description, is_publicated, thumbnail_path,
          publish_date, layout_id, is_slider, has_additional_image, has_additional_video,
          has_additional_file, has_additional_link, has_additional_text, kategori_content_id,
          created_by, updated_by, created_at, updated_at
        ) VALUES (
          5, r.title, r.slug, r.content, r.content,
          upper(r.status_content) = 'PUBLISH', r.thumbnail, r.publish_date::date, NULL,
          false, false, false, false, false, false, v_kategori_id,
          'legacy-import', 'legacy-import', COALESCE(r.publish_date::timestamp, now()), COALESCE(r.publish_date::timestamp, now())
        ) RETURNING id INTO v_detail_id;

      WHEN 'infographic' THEN
        IF EXISTS (SELECT 1 FROM content_detail_galleries WHERE slug = r.slug) THEN CONTINUE; END IF;
          content_id, title, description, slug, is_publicated, publish_date, layout_id,
          created_by, updated_by, created_at, updated_at
        ) VALUES (
          3, r.title, r.content, r.slug,
          upper(r.status_content) = 'PUBLISH', r.publish_date::date, NULL,
          'legacy-import', 'legacy-import', now(), now()
        ) RETURNING id INTO v_detail_id;
        IF r.thumbnail IS NOT NULL THEN
          VALUES (v_detail_id, NULL, NULL, r.thumbnail, 1, 'legacy-import', 'legacy-import', now(), now());
        END IF;

      WHEN 'event' THEN
        IF EXISTS (SELECT 1 FROM content_detail_agendas WHERE content_id = 4 AND event_name = r.title) THEN CONTINUE; END IF;
          content_id, event_name, is_active, is_range, datetime_start, datetime_end,
          created_by, updated_by, created_at, updated_at
        ) VALUES (
          4, r.title, upper(r.status_content) = 'PUBLISH', r.event_end_date IS NOT NULL,
          COALESCE(r.event_date::timestamp, r.publish_date::timestamp, now()), r.event_end_date::timestamp,
          'legacy-import', 'legacy-import', now(), now()
        ) RETURNING id INTO v_detail_id;

      ELSE
        CONTINUE;
    END CASE;
    IF v_detail_id IS NOT NULL THEN
    END IF;
  END LOOP;
END $$;

-- content tags
SELECT
  CASE m.entity WHEN 'publication' THEN 'App\Models\ContentDetailPublication' ELSE 'App\Models\ContentDetailGallery' END,
  m.detail_id, t.id, 'legacy-import', 'legacy-import', now(), now()
FROM _legacy_content_tags ct
JOIN _legacy_content_map m ON m.legacy_id = ct.legacy_content_id
JOIN _legacy_tags lt ON lt.title = ct.tag_title
JOIN ms_tags t ON t.title = lt.title;

-- additional files
SELECT 'App\Models\ContentDetailPublication', m.detail_id, f.file_name, f.file_url, NULL,
  row_number() OVER (PARTITION BY f.legacy_content_id ORDER BY f.file_name),
  'legacy-import', 'legacy-import', now(), now()
FROM _legacy_content_files f
JOIN _legacy_content_map m ON m.legacy_id = f.legacy_content_id;

-- reset sequences
SELECT setval('content_detail_publications_id_seq', GREATEST((SELECT COALESCE(MAX(id), 1) FROM content_detail_publications), 1));
SELECT setval('content_detail_galleries_id_seq', GREATEST((SELECT COALESCE(MAX(id), 1) FROM content_detail_galleries), 1));
SELECT setval('content_detail_agendas_id_seq', GREATEST((SELECT COALESCE(MAX(id), 1) FROM content_detail_agendas), 1));
SELECT setval('content_detail_gallery_lists_id_seq', GREATEST((SELECT COALESCE(MAX(id), 1) FROM content_detail_gallery_lists), 1));
SELECT setval('content_additional_files_id_seq', GREATEST((SELECT COALESCE(MAX(id), 1) FROM content_additional_files), 1));
SELECT setval('ms_tags_id_seq', GREATEST((SELECT COALESCE(MAX(id), 1) FROM ms_tags), 1));
SELECT setval('content_tags_id_seq', GREATEST((SELECT COALESCE(MAX(id), 1) FROM content_tags), 1));
SELECT setval('ms_kategori_contents_id_seq', GREATEST((SELECT COALESCE(MAX(id), 1) FROM ms_kategori_contents), 1));

DROP TABLE IF EXISTS _legacy_rows, _legacy_tags, _legacy_content_tags, _legacy_content_files, _legacy_content_map;
COMMIT;

